rules_version = '2';

service firebase.storage {
  match /b/{bucket}/o {

    // ========================================
    // HELPER FUNCTIONS
    // ========================================

    function isAuthenticated() {
      return request.auth != null && request.auth.token.firebase.sign_in_provider != 'anonymous';
    }

    function isOrgMember(orgId) {
      return isAuthenticated() && 
        firestore.exists(/databases/(default)/documents/organizations/$(orgId)) &&
        request.auth.uid in firestore.get(/databases/(default)/documents/organizations/$(orgId)).data.members;
    }

    // Guest explorer writes are retired. Keep this helper so legacy rule branches
    // stay syntactically stable, but make every guest path fail closed.
    function isGuest() {
      return false;
    }

    // File size limits (in bytes)
    function isUnderSizeLimit(maxMB) {
      return request.resource.size < maxMB * 1024 * 1024;
    }

    // Content type validation
    function isImageType() {
      return request.resource.contentType.matches('image/.*');
    }

    function isVideoType() {
      return request.resource.contentType.matches('video/.*');
    }

    function isAudioType() {
      return request.resource.contentType.matches('audio/.*');
    }

    function isAllowedMediaType() {
      return isImageType() || isVideoType() || isAudioType() ||
             request.resource.contentType.matches('application/pdf') ||
             request.resource.contentType.matches('application/json') ||
             request.resource.contentType.matches('text/.*') ||
             request.resource.contentType.matches('application/msword') ||
             request.resource.contentType.matches('application/vnd.openxmlformats-officedocument.wordprocessingml.document') ||
             request.resource.contentType.matches('application/zip') ||
             request.resource.contentType.matches('application/x-zip-compressed') ||
             request.resource.contentType.matches('font/.*') ||
             request.resource.contentType.matches('application/x-font-.*') ||
             request.resource.contentType.matches('application/font-woff.*');
    }

    // ========================================
    // USER-SPECIFIC STORAGE (Private)
    // ========================================

    // Trash Quarantine Vault: Owner-readable, client create/update/delete DENIED. Managed via backend Cloud Functions.
    match /users/{userId}/trash/{allPaths=**} {
      allow read: if isAuthenticated() && request.auth.uid == userId;
      allow write, delete: if false;
    }

    // Ephemeral / Cache paths: Client cleanup privileges allowed. Writes are
    // size-capped like the general user path so tmp cannot be used as an
    // unbounded storage hole; deletes stay unrestricted for cache hygiene.
    match /users/{userId}/tmp/{allPaths=**} {
      allow read, delete: if isAuthenticated() && request.auth.uid == userId;
      allow create, update: if isAuthenticated() &&
                              request.auth.uid == userId &&
                              isUnderSizeLimit(500);
    }

    // Ephemeral Audio Analysis Uploads: GCS lifecycle rules automatically delete
    // these temporary files after processing (1-day TTL). Authenticated owner can
    // upload audio files up to 500MB and delete immediately upon completion.
    match /tmp/audio-analysis/{userId}/{allPaths=**} {
      allow read, delete: if isAuthenticated() && request.auth.uid == userId;
      allow create, update: if isAuthenticated() &&
                              request.auth.uid == userId &&
                              isUnderSizeLimit(500) &&
                              isAudioType();
    }

    // Users general storage: Delete denied for clients (route through Trash).
    // topLevel exclusion is required because overlapping Storage matches are ORed.
    match /users/{userId}/{topLevel}/{allPaths=**} {
      allow read: if isAuthenticated() && request.auth.uid == userId;
      allow create, update: if isAuthenticated() &&
                              request.auth.uid == userId &&
                              topLevel != 'trash' &&
                              topLevel != 'tmp' &&
                              topLevel != 'rights' &&
                              isUnderSizeLimit(500) &&
                              isAllowedMediaType();
      allow delete: if isAuthenticated() &&
                      request.auth.uid == userId &&
                      topLevel in ['assets', 'thumbnails', 'audio', 'likeness', 'brandKit'];
    }

    match /users/{userId}/rights/deposits/{fileName} {
      allow read: if isAuthenticated() && request.auth.uid == userId;
      allow create: if isAuthenticated() && request.auth.uid == userId
        && resource == null && request.resource.size <= 500 * 1024 * 1024
        && request.resource.contentType in ['audio/wav', 'audio/mpeg', 'audio/mp4', 'audio/aiff', 'audio/flac', 'application/pdf'];
      allow update, delete: if false;
    }
    match /users/{userId}/rights/{category}/{allPaths=**} {
      allow read: if isAuthenticated() && request.auth.uid == userId;
      allow write: if false;
    }

    // Content-addressed source masters: the authenticated owner can create a
    // correctly identified audio object once, but clients can never replace or
    // delete it. Admin retention/backup controls remain server-side.
    match /masters/{userId}/{contentHash}/{fileName} {
      allow read: if isAuthenticated() && request.auth.uid == userId;
      allow create: if isAuthenticated() &&
                      request.auth.uid == userId &&
                      resource == null &&
                      contentHash.matches('^[a-f0-9]{64}$') &&
                      fileName.matches('^original\\.[A-Za-z0-9]{2,8}$') &&
                      isUnderSizeLimit(500) &&
                      isAudioType() &&
                      request.resource.metadata.keys().hasAll([
                        'contentHash', 'ownerId', 'immutable', 'masterFingerprint', 'originalFileName'
                      ]) &&
                      request.resource.metadata.contentHash == contentHash &&
                      request.resource.metadata.ownerId == request.auth.uid &&
                      request.resource.metadata.immutable == 'true' &&
                      request.resource.metadata.masterFingerprint is string &&
                      request.resource.metadata.masterFingerprint.size() > 0 &&
                      request.resource.metadata.masterFingerprint.size() <= 512 &&
                      request.resource.metadata.originalFileName is string &&
                      request.resource.metadata.originalFileName.size() > 0 &&
                      request.resource.metadata.originalFileName.size() <= 512;
      allow update, delete: if false;
    }

    // Canonical content-addressed RAG document sources: owner can create once,
    // clients cannot replace or delete. Server indexing & deletion control lifecycle.
    match /rag-sources/{userId}/{contentHash}/{fileName} {
      allow read: if isAuthenticated() && request.auth.uid == userId;
      allow create: if isAuthenticated() &&
                      request.auth.uid == userId &&
                      resource == null &&
                      contentHash.matches('^[a-f0-9]{64}$') &&
                      fileName.matches('^original\\.(txt|md|pdf)$') &&
                      isUnderSizeLimit(25) &&
                      (request.resource.contentType == 'text/plain' ||
                       request.resource.contentType == 'text/markdown' ||
                       request.resource.contentType == 'application/pdf') &&
                      request.resource.metadata.keys().hasAll([
                        'contentHash', 'ownerId', 'immutable', 'originalFileName'
                      ]) &&
                      request.resource.metadata.contentHash == contentHash &&
                      request.resource.metadata.ownerId == request.auth.uid &&
                      request.resource.metadata.immutable == 'true' &&
                      request.resource.metadata.originalFileName is string &&
                      request.resource.metadata.originalFileName.size() > 0 &&
                      request.resource.metadata.originalFileName.size() <= 512;
      allow update, delete: if false;
    }

    // Content-addressed release cover art: like masters, the owner may create
    // the exact identified bytes once. Desktop packaging re-measures the
    // downloaded bytes before DDEX delivery; clients cannot replace or remove
    // the provenance object afterward.
    match /covers/{userId}/{contentHash}/{fileName} {
      allow read: if isAuthenticated() && request.auth.uid == userId;
      allow create: if isAuthenticated() &&
                      request.auth.uid == userId &&
                      resource == null &&
                      contentHash.matches('^[a-f0-9]{64}$') &&
                      fileName.matches('^original\\.(jpe?g|png)$') &&
                      isUnderSizeLimit(50) &&
                      request.resource.contentType in ['image/jpeg', 'image/png'] &&
                      request.resource.metadata.keys().hasAll([
                        'contentHash', 'ownerId', 'immutable', 'originalFileName'
                      ]) &&
                      request.resource.metadata.contentHash == contentHash &&
                      request.resource.metadata.ownerId == request.auth.uid &&
                      request.resource.metadata.immutable == 'true' &&
                      request.resource.metadata.originalFileName is string &&
                      request.resource.metadata.originalFileName.size() > 0 &&
                      request.resource.metadata.originalFileName.size() <= 512;
      allow update, delete: if false;
    }

    // Creative Suite thin client asset uploads
    match /creative/{userId}/{allPaths=**} {
      // Owner can read their own uploaded assets and results
      allow read: if (isAuthenticated() && request.auth.uid == userId) || (isGuest() && userId == 'founder-demo-uid');
      allow delete: if isAuthenticated() && request.auth.uid == userId;
      // Owner can upload reference media; creation/update stays size and MIME gated.
      allow create, update: if ((isAuthenticated() && request.auth.uid == userId) || (isGuest() && userId == 'founder-demo-uid')) &&
                              isUnderSizeLimit(100) && // limit references to 100MB
                              (isImageType() || isVideoType() || isAudioType());
    }

    // ========================================
    // ORGANIZATION-SCOPED STORAGE
    // ========================================

    // Org members can access org storage
    match /orgs/{orgId}/{allPaths=**} {
      allow read: if isOrgMember(orgId);
      // Write: org member, under 500MB, valid media type
      allow write: if isOrgMember(orgId) &&
                      isUnderSizeLimit(500) &&
                      isAllowedMediaType();
    }

    // ========================================
    // PROJECT-SPECIFIC STORAGE
    // ========================================

    // Allow users to upload to their own folder within a project
    match /projects/{projectId}/{userId}/{allPaths=**} {
      allow read: if isAuthenticated() && request.auth.uid == userId
        && firestore.exists(/databases/(default)/documents/projects/$(projectId))
        && isOrgMember(firestore.get(/databases/(default)/documents/projects/$(projectId)).data.orgId);
      allow write: if isAuthenticated() && request.auth.uid == userId
        && firestore.exists(/databases/(default)/documents/projects/$(projectId))
        && isOrgMember(firestore.get(/databases/(default)/documents/projects/$(projectId)).data.orgId)
        && isUnderSizeLimit(1024)
        && isAllowedMediaType();
    }

    // ========================================
    // VIDEO STORAGE (User-generated content)
    // ========================================

    // User-uploaded and AI-generated videos (client-side uploads from Veo pipeline)
    match /videos/{userId}/{allPaths=**} {
      // Owner can read their own videos
      allow read: if isAuthenticated() && request.auth.uid == userId;
      // Owner can upload: authenticated, size ≤ 500MB, valid video type
      allow write: if isAuthenticated() &&
                      request.auth.uid == userId &&
                      isUnderSizeLimit(500) &&
                      isVideoType();
    }

    // ISSUE-1175: an authenticated owner may upload only the one staging
    // object authorized by its server-created videoSessions record. The
    // expected size, MIME type, path, and identity metadata must all agree.
    // Originals and derivatives are copied by Admin SDK workers and remain
    // client read-only; all client deletes are denied for auditability.
    match /session-media/{userId}/{sessionId}/staging/{fileName} {
      allow read: if isAuthenticated() && request.auth.uid == userId;
      allow create, update: if isAuthenticated() &&
        request.auth.uid == userId &&
        sessionId.matches('^[a-f0-9]{40}$') &&
        fileName.matches('^original\\.(mp4|mov|webm|m4v)$') &&
        firestore.exists(/databases/(default)/documents/videoSessions/$(sessionId)) &&
        firestore.get(/databases/(default)/documents/videoSessions/$(sessionId)).data.ownerUid == request.auth.uid &&
        firestore.get(/databases/(default)/documents/videoSessions/$(sessionId)).data.sessionId == sessionId &&
        firestore.get(/databases/(default)/documents/videoSessions/$(sessionId)).data.stagingPath ==
          'session-media/' + userId + '/' + sessionId + '/staging/' + fileName &&
        firestore.get(/databases/(default)/documents/videoSessions/$(sessionId)).data.expectedByteSize == request.resource.size &&
        firestore.get(/databases/(default)/documents/videoSessions/$(sessionId)).data.expectedMimeType == request.resource.contentType &&
        firestore.get(/databases/(default)/documents/videoSessions/$(sessionId)).data.status == 'uploading' &&
        request.resource.size > 0 &&
        request.resource.size <= 20 * 1024 * 1024 * 1024 &&
        request.resource.contentType in ['video/mp4', 'video/quicktime', 'video/webm', 'video/x-m4v'] &&
        request.resource.metadata.keys().hasAll([
          'ownerUid', 'organizationId', 'projectId', 'sessionId', 'uploadSessionId'
        ]) &&
        request.resource.metadata.ownerUid == userId &&
        request.resource.metadata.organizationId ==
          firestore.get(/databases/(default)/documents/videoSessions/$(sessionId)).data.organizationId &&
        request.resource.metadata.projectId ==
          firestore.get(/databases/(default)/documents/videoSessions/$(sessionId)).data.projectId &&
        request.resource.metadata.sessionId == sessionId &&
        request.resource.metadata.uploadSessionId ==
          firestore.get(/databases/(default)/documents/videoSessions/$(sessionId)).data.uploadSessionId;
      allow delete: if false;
    }

    match /session-media/{userId}/{sessionId}/{managedPath=**} {
      allow read: if isAuthenticated() && request.auth.uid == userId;
      allow write: if false;
    }

    // Video thumbnails (auto-generated poster frames)
    match /video-thumbnails/{userId}/{allPaths=**} {
      allow read: if isAuthenticated() && request.auth.uid == userId;
      allow write: if isAuthenticated() &&
                      request.auth.uid == userId &&
                      isUnderSizeLimit(10) &&
                      isImageType();
    }

    // ========================================
    // VIDEO GENERATION OUTPUT (System-managed)
    // ========================================

    // Private project renders are readable only through the authenticated
    // terminal-receipt callable, which verifies project membership, exact
    // object generation, revocation, and a maximum five-minute URL lifetime.
    match /private-renders/{userId}/{projectId}/{jobId}/{allPaths=**} {
      allow read, write: if false;
    }

    // Generated videos from Veo - read-only for users
    match /generated/{userId}/{allPaths=**} {
      allow read: if isAuthenticated() && request.auth.uid == userId;
      // Writes only allowed from Cloud Functions (no client writes)
      allow write: if false;
    }

    // ========================================
    // PUBLIC ASSETS (CDN)
    // ========================================

    // Public readable assets (e.g., thumbnails, shared media)
    match /public/{allPaths=**} {
      // SECURITY: Only authenticated users can read public assets (prevents scraper exfiltration)
      allow read: if isAuthenticated();
      // SECURITY: Restrict unauthorized writes to public assets
      allow write: if false;
    }

    // ========================================
    // STEM PACKS (verified artist uploads)
    // ========================================

    // Stem pack files uploaded by artists for marketplace
    match /stems/{userId}/{allPaths=**} {
      // The owner can read their own stems; buyers get access via signed URLs from Cloud Functions
      allow read: if isAuthenticated() && request.auth.uid == userId;
      // Owner can upload: verified, size ≤ 250MB, audio files only
      allow write: if isAuthenticated() &&
                      request.auth.uid == userId &&
                      isUnderSizeLimit(250) &&
                      isAudioType();
    }

    // ========================================
    // TAX DOCUMENTS (Sensitive PII — W-9/W-8BEN)
    // ========================================

    // Owner-uploaded tax forms for payment collaborators. Retention is the
    // artist's call, not ours (IRS recordkeeping duty falls on the taxpayer,
    // not the software) — artist may delete anytime. No update: a corrected
    // file is a new upload under a new fileName, keeping prior versions
    // addressable until the artist explicitly deletes them.
    match /tax_docs/{userId}/{collaboratorId}/{fileName} {
      allow read: if isAuthenticated() && request.auth.uid == userId;
      allow delete: if isAuthenticated() && request.auth.uid == userId;
      allow create: if isAuthenticated() &&
                      request.auth.uid == userId &&
                      isUnderSizeLimit(20) &&
                      request.resource.contentType in ['application/pdf', 'image/png', 'image/jpeg'];
      allow update: if false;
    }

    // ========================================
    // VIDEO RENDER RELAY (Desktop Jobs — ISSUE-1588)
    // ========================================

    match /video-render-jobs/{userId}/{allPaths=**} {
      allow read: if isAuthenticated() && request.auth.uid == userId;
      allow write: if isAuthenticated() &&
                      request.auth.uid == userId &&
                      isUnderSizeLimit(500) &&
                      isVideoType();
    }

    // ========================================
    // CEO SYNC ENCRYPTED BACKUP (ISSUE-1588)
    // ========================================

    match /ceo_sync/{userId}/{allPaths=**} {
      allow read: if isAuthenticated() && request.auth.uid == userId;
      allow write: if isAuthenticated() &&
                      request.auth.uid == userId &&
                      isUnderSizeLimit(100);
    }

    // ========================================
    // WHITE-GLOVE INGESTION (ISSUE-1588)
    // ========================================

    match /ingest/white-glove/{artistId}/{allPaths=**} {
      allow read: if isAuthenticated() && request.auth.uid == artistId;
      allow write: if isAuthenticated() &&
                      request.auth.uid == artistId &&
                      isUnderSizeLimit(500) &&
                      isAllowedMediaType();
    }

    // ========================================
    // DISTRIBUTION DELIVERY RECEIPTS (ISSUE-1588)
    // ========================================

    match /distribution/receipts/{releaseId}/{allPaths=**} {
      allow read: if isAuthenticated() &&
        firestore.exists(/databases/(default)/documents/releases/$(releaseId)) &&
        (('userId' in firestore.get(/databases/(default)/documents/releases/$(releaseId)).data &&
          firestore.get(/databases/(default)/documents/releases/$(releaseId)).data.userId == request.auth.uid) ||
         ('ownerId' in firestore.get(/databases/(default)/documents/releases/$(releaseId)).data &&
          firestore.get(/databases/(default)/documents/releases/$(releaseId)).data.ownerId == request.auth.uid));
      allow create: if isAuthenticated() &&
        resource == null &&
        isUnderSizeLimit(10) &&
        request.resource.contentType == 'application/json' &&
        firestore.exists(/databases/(default)/documents/releases/$(releaseId)) &&
        (('userId' in firestore.get(/databases/(default)/documents/releases/$(releaseId)).data &&
          firestore.get(/databases/(default)/documents/releases/$(releaseId)).data.userId == request.auth.uid) ||
         ('ownerId' in firestore.get(/databases/(default)/documents/releases/$(releaseId)).data &&
          firestore.get(/databases/(default)/documents/releases/$(releaseId)).data.ownerId == request.auth.uid));
      allow update, delete: if false;
    }

    // ========================================
    // APP RELEASES (Founders)
    // ========================================

    // Releases like DMG and EXE files
    match /founders/releases/{allPaths=**} {
      allow read: if isAuthenticated() && 
                  (firestore.get(/databases/(default)/documents/users/$(request.auth.uid)).data.subscriptionTier == 'founder' ||
                   firestore.get(/databases/(default)/documents/users/$(request.auth.uid)).data.tier == 'founder' ||
                   firestore.get(/databases/(default)/documents/users/$(request.auth.uid)).data.isFounder == true);
      allow write: if false; // Admin uploads only via Firebase Console or Admin SDK
    }

    // ========================================
    // DENY ALL OTHER ACCESS
    // ========================================

    // Any paths not explicitly matched above are denied by default
  }
}
