// --- Rational Time Primitives ---
export interface RationalTime {
  /** Presentation time stamp as integer */
  pts: bigint;
  /** Standard base timescale: 60000 (allows 23.976, 24, 29.97, 30, 60 fps integer mapping) */
  timescale: number;
}

export interface TimeRange {
  start: RationalTime;
