import type { Input, VideoSampleSink } from 'mediabunny';
import { resolveStorageUrl } from '@/services/storage/resolveStorageUrl';

/** One lazily opened media file. The caller owns each returned VideoFrame. */
export class NLEVideoSource {
  private input: Input | null = null;
  private sink: Promise<VideoSampleSink> | null = null;
  private closed = false;

  constructor(private readonly uri: string) {}

  private async open(): Promise<VideoSampleSink> {
    const { Input, ALL_FORMATS, UrlSource, VideoSampleSink } = await import('mediabunny');
    const url = await resolveStorageUrl(this.uri);
    if (this.closed) throw new Error('Video source was closed.');
    const input = new Input({
      formats: ALL_FORMATS,
      source: new UrlSource(url, {
        maxCacheSize: 8 * 1024 * 1024,
        getRetryDelay: (attempt) => attempt < 2 ? 0.5 : null,
      }),
    });
    this.input = input;
    const track = await input.getPrimaryVideoTrack();
    if (!track || !await track.canDecode()) {
      throw new Error('This video cannot be decoded by this browser.');
    }
    return new VideoSampleSink(track);
  }

  async getFrameAt(seconds: number): Promise<VideoFrame | null> {
    if (this.closed) return null;
    const sink = await (this.sink ??= this.open());
    const sample = await sink.getSample(seconds);
    if (!sample) return null;
    try {
      return this.closed ? null : sample.toVideoFrame();
    } finally {
      sample.close();
    }
  }

  close(): void {
    this.closed = true;
    this.input?.dispose();
    this.input = null;
  }
}

import type { IndiiVideoProject } from '@indii/shared';
import { projectToTimelineAST, isClipActive, getSourceOffsetPts } from '@indii/video-compiler';
import { NLEVideoSource } from './NLEVideoSource';
import { computeTransformMatrix, type RenderLayer, type WebGL2Compositor } from './WebGL2Compositor';

/** Serializes decoding and coalesces scrub requests to the latest playhead. */
export class NLEFrameRenderer {
  private readonly ast;
  private readonly sources = new Map<string, NLEVideoSource>();
  private pending: bigint | null = null;
  private running = false;
  private closed = false;

  constructor(
    project: IndiiVideoProject,
    private readonly compositor: WebGL2Compositor,
    private readonly onError: (error: unknown) => void,
  ) {
    this.ast = projectToTimelineAST(project, 60000);
    for (const clip of project.clips) {
      if (clip.type === 'video' && clip.src) {
        this.sources.set(clip.id, new NLEVideoSource(clip.src));
      }
    }
  }

  request(pts: bigint): void {
    if (this.closed) return;
    this.pending = pts;
    if (!this.running) void this.renderPending();
  }

  private async renderPending(): Promise<void> {
    this.running = true;
    try {
      while (!this.closed && this.pending !== null) {
        const pts = this.pending;
        this.pending = null;
        const layers: RenderLayer[] = [];
        try {
          for (const track of this.ast.tracks) {
            if (track.type !== 'video' || track.muted) continue;
            for (const clip of track.clips) {
              if (clip.type !== 'video' || !isClipActive(pts, clip)) continue;
              const source = this.sources.get(clip.id);
              if (!source) continue;
              const seconds = Number(getSourceOffsetPts(pts, clip, 60000)) / 60000;
              const frame = await source.getFrameAt(seconds);
              if (frame) layers.push({ frame, transform: computeTransformMatrix(clip.transform), opacity: clip.transform.opacity });
            }
          }
          if (this.closed || this.pending !== null) {
            for (const layer of layers) (layer.frame as VideoFrame).close();
          } else {
            this.compositor.renderTick(layers);
          }
        } catch (error) {
          for (const layer of layers) (layer.frame as VideoFrame).close();
          if (!this.closed) this.onError(error);
          this.pending = null;
        }
      }
    } finally {
      this.running = false;
    }
  }

  close(): void {
    this.closed = true;
    this.pending = null;
    for (const source of this.sources.values()) source.close();
    this.sources.clear();
  }
}

