import { NLEVideoSource } from '/tmp/indii-1616-main/packages/renderer/src/services/video/nle/NLEVideoSource';
import { NLEFrameRenderer } from '/tmp/indii-1616-main/packages/renderer/src/services/video/nle/NLEFrameRenderer';
import { WebGL2Compositor } from '/tmp/indii-1616-main/packages/renderer/src/services/video/nle/WebGL2Compositor';
const check = (value, message) => { if (!value) throw new Error(message); };
window.runChecks = async () => {
  const source = new NLEVideoSource('/colors.mp4');
  const pixelCanvas = document.createElement('canvas');
  pixelCanvas.width = 320; pixelCanvas.height = 180;
  const ctx = pixelCanvas.getContext('2d');
  const colors = [];
  for (const seconds of [0.25, 1.25, 0.5]) {
    const frame = await source.getFrameAt(seconds);
    check(frame && frame.codedWidth === 320, 'Decoded source dimensions');
    ctx.drawImage(frame, 0, 0);
    colors.push(Array.from(ctx.getImageData(160, 90, 1, 1).data));
    frame.close();
  }
  source.close();
  check(await source.getFrameAt(0) === null, 'Closed source must retain no new frame');
  check(colors[0][0] > 180 && colors[0][2] < 50, 'First seek must be red');
  check(colors[1][2] > 180 && colors[1][0] < 50, 'Forward seek must be blue');
  check(colors[2][0] > 180 && colors[2][2] < 50, 'Backward seek must return red');

  const canvas = document.createElement('canvas');
  canvas.width = 320; canvas.height = 180;
  document.body.append(canvas);
  const gl = canvas.getContext('webgl2', { preserveDrawingBuffer: true });
  check(gl, 'WebGL2 must be available');
  const compositor = new WebGL2Compositor(gl);
  const render = compositor.renderTick.bind(compositor);
  const rendered = [];
  compositor.renderTick = (layers) => {
    const frames = layers.map(layer => layer.frame);
    render(layers);
    const pixel = new Uint8Array(4);
    gl.readPixels(160, 90, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, pixel);
    check(frames.every(frame => frame.codedWidth === 0), 'Compositor must close each delivered frame');
    rendered.push(Array.from(pixel));
  };
  const project = {id:'encoded-vector',name:'Encoded vector',fps:30,width:320,height:180,durationInFrames:60,
    tracks:[{id:'video',type:'video',name:'Video'}],
    clips:[{id:'clip',type:'video',src:'/colors.mp4',trackId:'video',name:'Colors',startFrame:15,durationInFrames:45,playbackRate:2}]};
  let error;
  const renderer = new NLEFrameRenderer(project, compositor, cause => {error = cause;});
  const waitFor = async (count) => {
    const start = performance.now();
    while (rendered.length < count && !error && performance.now()-start < 10000) await new Promise(r=>setTimeout(r,10));
    if(error) throw error;
    check(rendered.length >= count, 'Renderer must deliver a frame');
  };
  renderer.request(45000n);
  await waitFor(1);
  check(rendered[0][0] > 180, 'Timeline offset and speed must display red');
  renderer.request(67500n);
  await waitFor(2);
  check(rendered[1][2] > 180, 'Timeline offset and speed must display blue');
  renderer.close(); compositor.dispose();
  return {colors,rendered,checks:'decoded MP4 frames, forward/backward seeks, timeline offset, playback speed, GPU upload, delivered frame disposal, closed source'};
};
