 * only use these; anything else renders non-deterministically or fails
 * closed in cloud renders, so the compiler rejects unknown families.
 */
export const EMBEDDED_TEXT_FONT_FAMILIES = [
    'Archivo Black',
    'Space Mono',
    'Montserrat',
    'Oswald',
    'League Gothic',
    'JetBrains Mono',
    'IBM Plex Mono',
    'Source Code Pro',
] as const;

export type EmbeddedTextFontFamily = (typeof EMBEDDED_TEXT_FONT_FAMILIES)[number];
import { describe, it, expect } from 'vitest';
import { projectToTimelineAST, timelineASTToProject } from './nleProjectBridge.js';
import type { IndiiVideoProject } from '@indii/shared';

describe('NLE Project Model Bridge (Issue #413 Phase 4)', () => {
  const sampleProject: IndiiVideoProject = {
    id: 'proj_alpha',
    name: 'Music Video Promo',
    fps: 30,
    durationInFrames: 300,
    width: 1920,
    height: 1080,
    tracks: [
      { id: 't_video_1', type: 'video', name: 'Main Video Track', isMuted: false, isLocked: false },
      { id: 't_audio_1', type: 'audio', name: 'Master Audio Track', isMuted: false, isLocked: false },
    ],
    clips: [
      {
        id: 'c_v1',
        name: 'Intro Hook',
        type: 'video',
        src: 'https://cdn.indii.music/intro.mp4',
        trackId: 't_video_1',
        startFrame: 0,
        durationInFrames: 90, // 3 seconds at 30fps
        x: 0,
        y: 0,
        scale: 1.0,
        rotation: 0,
        opacity: 0.85,
        anchorX: 0.5,
        anchorY: 0.5,
