                database.close();
                resolve();
            };
            transaction.onerror = () => {
                database.close();
                reject(transaction.error ?? new Error(`Unable to clear ${name}`));
            };
            transaction.onabort = () => {
                database.close();
                reject(transaction.error ?? new Error(`Cleanup of ${name} was aborted`));
