export const healthCheck = onRequest(
    {
        secrets: [arcjetKey],
        timeoutSeconds: 60, memory: "512MiB",
        cpu: 'gcf_gen1',
        concurrency: 1,
    },
    async (req, res) => {
        const protection = await protectAnonymousSignupRequest(req as never, 'health-check', 'allow-low-risk-read');
        if (!protection.allowed) {
            res.status(protection.status || 429).json({ error: protection.message || 'Too Many Requests' });
            return;
        }

        const status: Record<string, unknown> = {
            status: "ok",
            timestamp: new Date().toISOString(),
            version: "0.1.0-beta.2",
            region: process.env.FUNCTION_REGION || "us-central1",
        };

        // Check Firestore connectivity
        try {
            await admin.firestore().collection("_health").doc("ping").set({
                lastCheck: admin.firestore.FieldValue.serverTimestamp()
            }, { merge: true });
            status.firestore = "connected";
        } catch (error: unknown) {
            status.firestore = "error";
            status.status = "degraded";
            // Surface the real cause (e.g. IAM permission-denied) instead of
