import type { IndiiVideoClip, IndiiVideoProject } from '@indii/shared';
import { resolveStorageUrl } from '@/services/storage/resolveStorageUrl';

/** Timeline-to-source mapping shared by startup, seek and steady playback. */
export function previewAudioState(clip: IndiiVideoClip, frame: number, fps: number) {
  const rate = Math.max(0.25, Math.min(4, clip.playbackRate ?? 1));
  const localSeconds = (frame - clip.startFrame) / fps;
  const duration = clip.durationInFrames / fps;
  const sourceSeconds = (clip.sourceInUs ?? 0) / 1_000_000 + localSeconds * rate;
  const sourceEnd = clip.sourceOutUs === undefined ? Infinity : clip.sourceOutUs / 1_000_000;
  const active = localSeconds >= 0 && localSeconds < duration && sourceSeconds < sourceEnd;
  const fadeIn = clip.audioFade?.inSeconds ?? 0;
  const fadeOut = clip.audioFade?.outSeconds ?? 0;
  const fade = Math.min(1, fadeIn > 0 ? localSeconds / fadeIn : 1,
    fadeOut > 0 ? (duration - localSeconds) / fadeOut : 1);
  return { active, sourceSeconds, rate, gain: Math.max(0, Math.min(1, (clip.volume ?? 1) * fade)) };
}

/** Bounded active-clip media readers. Browser pitch preservation stays enabled. */
export class NLEPreviewAudio {
  private entries = new Map<string, { media: HTMLAudioElement; node: MediaElementAudioSourceNode; pending: boolean }>();
  private opening = new Set<string>();
  private generation = 0;
  private closed = false;
  private playing = false;
  private frame = 0;
  private forceSeek = false;

  constructor(private readonly project: IndiiVideoProject, private readonly context: AudioContext,
    private readonly onError: (error: unknown) => void) {}

  sync(frame: number, playing: boolean, seek = false): void {
    if (this.closed) return;
    this.frame = frame;
    this.playing = playing;
    this.forceSeek = seek;
    const solo = this.project.tracks.some(track => track.isSolo);
    const active = this.project.clips.filter(clip => {
      const track = this.project.tracks.find(candidate => candidate.id === clip.trackId);
      return clip.src && (clip.type === 'audio' || clip.type === 'video' && clip.hasAudio === true)
        && !track?.isMuted && (!solo || track?.isSolo)
        && previewAudioState(clip, frame, this.project.fps).active;
    });
    const ids = new Set(active.map(clip => clip.id));
    for (const [id, entry] of this.entries) {
      if (!ids.has(id)) {
        this.release(entry);
        this.entries.delete(id);
      }
    }
    for (const clip of active) {
      const entry = this.entries.get(clip.id);
      if (entry) this.update(clip, entry);
      else if (playing && !this.opening.has(clip.id)) void this.open(clip);
    }
  }

  private async open(clip: IndiiVideoClip): Promise<void> {
    const generation = this.generation;
    this.opening.add(clip.id);
    try {
      const url = await resolveStorageUrl(clip.src!);
      if (this.closed || generation !== this.generation || !this.playing
        || !previewAudioState(clip, this.frame, this.project.fps).active) return;
      const media = new Audio();
      media.crossOrigin = 'anonymous';
      media.preload = 'auto';
      media.preservesPitch = true;
      media.src = url;
      const node = this.context.createMediaElementSource(media);
      node.connect(this.context.destination);
      const entry = { media, node, pending: false };
      this.entries.set(clip.id, entry);
      media.onerror = () => { if (!this.closed) this.onError(new Error(`Audio preview could not load ${clip.name}.`)); };
      this.update(clip, entry, true);
    } catch (error) {
      if (!this.closed && generation === this.generation) this.onError(error);
    } finally {
      this.opening.delete(clip.id);
    }
  }

  private update(clip: IndiiVideoClip, entry: { media: HTMLAudioElement; pending: boolean }, initial = false): void {
    const state = previewAudioState(clip, this.frame, this.project.fps);
    const media = entry.media;
    media.volume = state.gain;
    media.playbackRate = state.rate;
    if (initial || this.forceSeek || Math.abs(media.currentTime - state.sourceSeconds) > 0.08) {
      media.currentTime = Math.max(0, state.sourceSeconds);
    }
    if (!this.playing) media.pause();
    else if (media.paused && !entry.pending) {
      entry.pending = true;
      void media.play().catch(error => {
        if (!this.closed && this.playing && this.entries.get(clip.id) === entry
          && !(error instanceof DOMException && error.name === 'AbortError')) this.onError(error);
      }).finally(() => { entry.pending = false; if (!this.playing || this.closed || this.entries.get(clip.id) !== entry) media.pause(); });
    }
  }

  pause(): void {
    this.playing = false;
    this.generation++;
    for (const entry of this.entries.values()) entry.media.pause();
  }

  private release(entry: { media: HTMLAudioElement; node: MediaElementAudioSourceNode }): void {
    entry.media.onerror = null;
    entry.media.pause();
    entry.node.disconnect();
    entry.media.removeAttribute('src');
    entry.media.load();
  }

  close(): void {
    this.closed = true;
    this.pause();
    for (const entry of this.entries.values()) this.release(entry);
    this.entries.clear();
  }
}
import { useState, useRef, useEffect, useCallback } from 'react';
import type { IndiiVideoProject } from '@indii/shared';
import { NLEPreviewAudio } from './NLEPreviewAudio';
import { MasterAudioClock } from './MasterAudioClock';
import { NLEFrameRenderer } from './NLEFrameRenderer';
import { WebGL2Compositor } from './WebGL2Compositor';
import { logger } from '@/utils/logger';

export interface UseNLEPlaybackOptions {
  project: IndiiVideoProject;
  canvas: HTMLCanvasElement | null;
  onFrameUpdate?: (frame: number) => void;
  onEnded?: () => void;
}

export interface UseNLEPlaybackReturn {
  isPlaying: boolean;
  error: string | null;
  retry: () => void;
  currentFrame: number;
  currentSeconds: number;
  play: () => void;
  pause: () => void;
  seekToFrame: (frame: number) => void;
  seekToSeconds: (seconds: number) => void;
}

export function useNLEPlayback({
  project,
  canvas,
  onFrameUpdate,
  onEnded,
}: UseNLEPlaybackOptions): UseNLEPlaybackReturn {
  const [isPlaying, setIsPlaying] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [revision, setRevision] = useState(0);
  const retry = useCallback(() => setRevision(value => value + 1), []);
  const [currentFrame, setCurrentFrame] = useState(0);

  const fps = project.fps > 0 ? project.fps : 30;
  const currentSeconds = currentFrame / fps;

  const audioCtxRef = useRef<AudioContext | null>(null);
  const previewAudioRef = useRef<NLEPreviewAudio | null>(null);
  const clockRef = useRef<MasterAudioClock | null>(null);
  const compositorRef = useRef<WebGL2Compositor | null>(null);
  const frameRendererRef = useRef<NLEFrameRenderer | null>(null);
  const rafIdRef = useRef<number | null>(null);
  const currentFrameRef = useRef<number>(0);

  // Keep ref synchronized with state
  currentFrameRef.current = currentFrame;

  // Initialize WebGL2 Compositor and Web Audio Master Clock
  useEffect(() => {
    if (!canvas) return;
    setError(null);

    try {
      const gl = canvas.getContext('webgl2') as WebGL2RenderingContext | null;
      if (gl && typeof gl.createShader === 'function') {
        const compositor = new WebGL2Compositor(gl);
        compositorRef.current = compositor;
        frameRendererRef.current = new NLEFrameRenderer(project, compositor, (cause) => {
          setError(cause instanceof Error ? cause.message : 'Video preview could not decode this media.');
          if (rafIdRef.current !== null) cancelAnimationFrame(rafIdRef.current);
          rafIdRef.current = null;
          clockRef.current?.pause();
          previewAudioRef.current?.pause();
          setIsPlaying(false);
        });
        frameRendererRef.current.request(BigInt(Math.round(currentFrameRef.current * 60000 / fps)));
      } else {
        setError('WebGL2 is unavailable in this browser.');
      }
    } catch (err) {
      logger.error('[useNLEPlayback] Failed to initialize WebGL2Compositor:', err);
      setError('The NLE preview could not initialize.');
    }

    const AudioContextClass =
      typeof window !== 'undefined'
        ? window.AudioContext ||
          (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
        : undefined;

    let audioCtx: AudioContext | null = null;
    if (AudioContextClass) {
      try {
        audioCtx = new AudioContextClass();
        audioCtxRef.current = audioCtx;
        previewAudioRef.current = new NLEPreviewAudio(project, audioCtx, (cause) => {
          setError(cause instanceof Error ? cause.message : 'Audio preview failed.');
          clockRef.current?.pause();
          previewAudioRef.current?.pause();
          if (rafIdRef.current !== null) cancelAnimationFrame(rafIdRef.current);
          rafIdRef.current = null;
          setIsPlaying(false);
        });
      } catch {
        // Fall back to software timing if hardware audio context throws
      }
    }

    if (!audioCtx && project.clips.some(clip => clip.type === 'audio' || clip.hasAudio === true)) {
      setError('Web Audio is unavailable. Audio preview cannot start in this browser.');
    }
    const fallbackCtx = {
      get currentTime() {
        return typeof performance !== 'undefined' ? performance.now() / 1000 : Date.now() / 1000;
      },
      state: 'running' as AudioContextState,
      resume: async () => {},
    };

    clockRef.current = new MasterAudioClock(audioCtx ?? fallbackCtx, 60000);

    return () => {
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current);
        rafIdRef.current = null;
      }
      previewAudioRef.current?.close();
      previewAudioRef.current = null;
      frameRendererRef.current?.close();
      frameRendererRef.current = null;
      if (compositorRef.current) {
        compositorRef.current.dispose();
        compositorRef.current = null;
      }
      if (audioCtxRef.current) {
        void audioCtxRef.current.close().catch(() => {});
        audioCtxRef.current = null;
      }
      clockRef.current = null;
      setIsPlaying(false);
    };
  }, [canvas, project, fps, revision]);

  const renderAtPts = useCallback((pts: bigint) => {
    frameRendererRef.current?.request(pts);
  }, []);

  const pause = useCallback(() => {
    if (rafIdRef.current !== null) {
      cancelAnimationFrame(rafIdRef.current);
      rafIdRef.current = null;
    }
    if (clockRef.current) {
      clockRef.current.pause();
    }
    previewAudioRef.current?.pause();
    setIsPlaying(false);
  }, []);

  const play = useCallback(() => {
    const audioCtx = audioCtxRef.current;
    const clock = clockRef.current;
    if (!clock || error) return;
    if (rafIdRef.current !== null) cancelAnimationFrame(rafIdRef.current);

    if (audioCtx && audioCtx.state === 'suspended') {
      void audioCtx.resume().catch((cause: unknown) => {
        setError(cause instanceof Error ? cause.message : 'Audio playback could not start.');
        pause();
      });
    }

    const startPts = BigInt(Math.round((currentFrameRef.current * 60000) / fps));
    clock.play(startPts);
    previewAudioRef.current?.sync(currentFrameRef.current, true, true);
    setIsPlaying(true);

    const tick = () => {
      if (!clockRef.current) return;
      const pts = clockRef.current.getCurrentPts();
      const frame = Math.round((Number(pts) * fps) / 60000);

      if (project.durationInFrames > 0 && frame >= project.durationInFrames) {
        pause();
        setCurrentFrame(project.durationInFrames);
        onFrameUpdate?.(project.durationInFrames);
        onEnded?.();
        return;
      }

      setCurrentFrame(frame);
      onFrameUpdate?.(frame);
      previewAudioRef.current?.sync(Number(pts) * fps / 60000, true);
      renderAtPts(pts);

      rafIdRef.current = requestAnimationFrame(tick);
    };

    rafIdRef.current = requestAnimationFrame(tick);
  }, [error, fps, onEnded, onFrameUpdate, pause, project.durationInFrames, renderAtPts]);

  const seekToFrame = useCallback(
    (frame: number) => {
      const clamped = Math.max(0, Math.min(frame, project.durationInFrames || frame));
      setCurrentFrame(clamped);
      currentFrameRef.current = clamped;
      onFrameUpdate?.(clamped);

      previewAudioRef.current?.sync(clamped, isPlaying, true);
      const targetPts = BigInt(Math.round((clamped * 60000) / fps));

      if (isPlaying && clockRef.current) {
        clockRef.current.play(targetPts);
      } else {
        renderAtPts(targetPts);
      }
    },
    [fps, isPlaying, onFrameUpdate, project.durationInFrames, renderAtPts]
  );

  const seekToSeconds = useCallback(
    (seconds: number) => {
      const targetFrame = Math.round(seconds * fps);
      seekToFrame(targetFrame);

