    private getDescendants(nodeId: string, graph: AgentGraph): string[] {
        const descendants: string[] = [];
        const queue = [nodeId];
        const visited = new Set<string>();

        while (queue.length > 0) {
            const current = queue.shift()!;
            if (visited.has(current)) continue;
            visited.add(current);

            const children = graph.edges
                .filter(e => e.sourceId === current)
                .map(e => e.targetId);

            for (const child of children) {
                descendants.push(child);
                queue.push(child);
            }
        }
        return Array.from(new Set(descendants));
    }

    /**
     * The main execution loop for the graph.
     * Continues as long as there are nodes ready to be executed.
     */
    private async runGraphLoop(
        userId: string,
        graph: AgentGraph,
        executionId: string,
        context: AgentContext,
        traceId: string,
        initialInput?: string
    ): Promise<string> {
        if (this.activeLoops.has(executionId)) {
            throw new Error(`Graph execution ${executionId} already has an active loop.`);
        }
        this.activeLoops.add(executionId);

        const runnerId = uuidv4();
        let heartbeatTimer: ReturnType<typeof setInterval> | undefined;
        let leaseAcquired = false;

        try {
            leaseAcquired = await this.acquireGraphLease(userId, executionId, runnerId);
            if (!leaseAcquired) {
                throw new Error(`Graph execution ${executionId} is locked by another runner.`);
            }

            // Arm 5-second lease heartbeat
            heartbeatTimer = setInterval(() => {
                this.acquireGraphLease(userId, executionId, runnerId, true).catch(err => {
                    logger.warn(`[AgentGraph] Heartbeat lease renewal failed for ${executionId}:`, err);
                });
            }, 5000);

            return await this.runGraphLoopInternal(userId, graph, executionId, runnerId, context, traceId, initialInput);
        } finally {
            if (heartbeatTimer) {
                clearInterval(heartbeatTimer);
            }
            if (leaseAcquired) {
                await this.releaseGraphLease(userId, executionId, runnerId);
            }
            this.activeLoops.delete(executionId);
        }
    }

    /**
     * Atomically acquire or renew a distributed execution lease on the graph execution document.
     * Prevents multi-instance concurrent graph execution loops while allowing expired leases (>20s) to be claimed.
     */
    private async acquireGraphLease(
        userId: string,
        executionId: string,
        runnerId: string,
        renewOnly = false
    ): Promise<boolean> {
        const ref = doc(db, 'users', userId, 'graphExecutions', executionId);
        try {
            return await runTransaction(db, async (tx) => {
                const snap = await tx.get(ref);
                if (!snap.exists()) return false;
                const data = (typeof (snap as any).data === 'function' ? (snap as any).data() : (snap as any).data) as GraphExecutionState;
                const now = Date.now();
                const existingLease = currentGraphLease(data);

                if (renewOnly && (existingLease?.holderId !== runnerId || existingLease.expiresAt <= now)) {
                    return false;
                }

                if (existingLease && existingLease.expiresAt > now && existingLease.holderId !== runnerId) {
                    logger.warn(`[AgentGraph] Execution ${executionId} is actively leased by ${existingLease.holderId} until ${new Date(existingLease.expiresAt).toISOString()}`);
                    return false;
                }

                tx.update(ref, {
                    'metadata.lease': {
                        holderId: runnerId,
                        acquiredAt: existingLease?.holderId === runnerId ? existingLease.acquiredAt : now,
                        expiresAt: now + 20000,
                    },
                    updatedAt: serverTimestamp(),
                });
                return true;
            });
        } catch (error) {
            logger.warn(`[AgentGraph] Failed to acquire distributed lease for ${executionId}:`, error);
            throw error;
        }
    }

    private async releaseGraphLease(
        userId: string,
        executionId: string,
        runnerId: string

                // Convert protocol back to AgentGraph
                const agentGraph = {
                    id: protocol.id,
                    name: protocol.name,
                    entryNodeId: protocol.steps.find(s => !protocol.edges.some(e => e.to === s.id))?.id || protocol.steps[0]?.id || '',
                    nodes: protocol.steps.map(s => ({
                        id: s.id,
                        // eslint-disable-next-line @typescript-eslint/no-explicit-any
                        agentId: s.agentId as any,
                        taskTemplate: s.prompt,
                        waitCondition: 'all' as const
                    })),
                    edges: protocol.edges.map(e => ({
                        sourceId: e.from,
                        targetId: e.to
                    })),
                    description: protocol.description || '',
                    metadata: { version: '1.0', author: 'system', createdAt: new Date().getTime() }
                };

                const executionState = await agentGraphStateService.createExecution(user.uid, agentGraph);
                const executionId = executionState.executionId;

                // Start polling state to update UI nodes
                const interval = setInterval(async () => {
                    const state = await agentGraphStateService.getExecution(user.uid, executionId);
                    if (!state) return;

                    setNodes(currentNodes => currentNodes.map(node => {
                        const nodeState = state.nodeStates[node.id];
                        if (nodeState) {
                            let status = Status.PENDING;
                            if (nodeState.status === 'EXECUTING_GENERATION') status = Status.WORKING;
                            if (nodeState.status === 'STEP_COMPLETE') status = Status.DONE;
                            if (nodeState.status === 'FAILED') status = Status.ERROR;

                            return { ...node, data: { ...node.data, status, output: nodeState.output } };
                        }
                        return node;
                    }));

                    if (state.status === 'COMPLETED' || state.status === 'FAILED' || state.status === 'CANCELLED') {
                        clearInterval(interval);
                        setIsRunning(false);
                    }
                }, 1000);

                agentGraphService.executeGraph(
                    agentGraph,
                    { userId: user.uid, traceId: `manual-run-${crypto.randomUUID()}` },
                    '', // initial input
                    executionId
                ).catch(async (e: unknown) => {
                    logger.error("Background graph execution failed", e);
                    clearInterval(interval);
                    setIsRunning(false);
                    toastError(`Workflow failed: ${e instanceof Error ? e.message : 'Unknown error'}`);
                    await agentGraphStateService.finalizeStatus(user.uid, executionId, 'FAILED').catch((stateError: unknown) => {
                        logger.error('Failed to persist workflow failure', stateError);
                    });
                });

                // Note: We don't await the interval here because the UI should show the "Running" state while polling
                return;
            } else {
                const engine = new WorkflowEngine(nodes, edges, setNodes);
                await engine.run();
            }
        } catch (e: unknown) {
            logger.error("Workflow failed", e);
            setIsRunning(false);
        }
        if (!currentWorkflowId?.startsWith('protocol-')) {
            setIsRunning(false);
        }
    };

