import React, { useState } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { useShallow } from 'zustand/react/shallow';
import { useStore } from '@/core/store';
import {
    MessageCircle, Image, Film, Music,
    Maximize2, Clock, Sparkles, X, LucideIcon
} from 'lucide-react';

/* ── type badge config ───────────────────────────────────────────── */
const BADGE: Record<string, { icon: LucideIcon; label: string; cls: string }> = {
    image: { icon: Image, label: 'Image', cls: 'text-blue-400 bg-blue-500/15' },
    video: { icon: Film, label: 'Video', cls: 'text-green-400 bg-green-500/15' },
    music: { icon: Music, label: 'Audio', cls: 'text-amber-400 bg-amber-500/15' },
    text: { icon: Sparkles, label: 'Text', cls: 'text-emerald-400 bg-emerald-500/15' },
};

function relTime(ts: number) {
    const d = Date.now() - ts;
    const m = Math.floor(d / 60000);
    if (m < 1) return 'Just now';
    if (m < 60) return `${m}m ago`;
    const h = Math.floor(m / 60);
    if (h < 24) return `${h}h ago`;
    const days = Math.floor(h / 24);
    if (days < 7) return `${days}d ago`;
    return new Date(ts).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

/**
 * AssetSpotlight — vertical grid of recent creative assets.
 * Fits inside a sidebar panel. Click to expand details.
 */
export default function AssetSpotlight() {
    const {
        generatedHistory,
        setModule,
        setSelectedItem,
        setRightPanelTab,
        setRightPanelView,
    } = useStore(
        useShallow((s) => ({
            generatedHistory: s.generatedHistory,
            setModule: s.setModule,
            setSelectedItem: s.setSelectedItem,
            setRightPanelTab: s.setRightPanelTab,
            setRightPanelView: s.setRightPanelView,
        }))
    );

    const [selIdx, setSelIdx] = useState<number | null>(null);
    const assets = generatedHistory.slice(0, 12);

    const handleDiscuss = async (asset: (typeof assets)[0]) => {
        const label = asset.type || 'creation';
        useStore.setState({
            commandBarInput: `Let's discuss this ${label} I created: "${asset.prompt?.slice(0, 80) ?? ''}"`,
        });

        if (asset.url) {
            try {
                const response = await fetch(asset.url);
                const blob = await response.blob();
                const file = new File([blob], `asset_${asset.id}.${blob.type.split('/')[1] || 'png'}`, { type: blob.type });
                useStore.setState(state => ({
                    commandBarAttachments: [...(state.commandBarAttachments || []), file]
                }));
            } catch (error) {
                console.error('Failed to fetch asset for attachment:', error);
            }
        }

        const canMountPanel = typeof window !== 'undefined' && window.innerWidth >= 768;
        if (canMountPanel) {
            useStore.setState({ isRightPanelOpen: true });
            setRightPanelTab('agent');
            setRightPanelView('messages');
        } else {
            useStore.setState({ currentModule: 'agent' as import('@/core/constants').ModuleId });
        }
    };

    const openInStudio = (asset: (typeof assets)[0]) => {
        setSelectedItem(asset);
        setModule('creative');
        setRightPanelTab('context');
    };

    /* ── empty state ─────────────────────────────────────────────── */
    if (assets.length === 0) {
        return (
            <div className="bg-[#161b22]/50 border border-white/5 rounded-xl p-4">
                <div className="flex items-center gap-2 mb-3">
                    <Sparkles size={14} className="text-green-400" />
                    <h3 className="text-xs font-bold text-white uppercase tracking-wider">Your Creations</h3>
                </div>
                <div className="flex items-center justify-center py-6 text-center">
                    <div>
                        <div className="w-10 h-10 rounded-xl bg-gray-800/50 flex items-center justify-center mx-auto mb-2">
                            <Image size={18} className="text-gray-600" />
                        </div>
                        <p className="text-xs text-gray-400 mb-0.5">No creations yet</p>
                        <p className="text-[10px] text-gray-600">Generate images, videos, or music</p>
                    </div>
                </div>
            </div>
        );
    }

    const sel = selIdx !== null ? assets[selIdx] : null;

    return (
        <div className="bg-[#161b22]/50 border border-white/5 rounded-xl p-3">
            {/* Header */}
            <div className="flex items-center gap-2 mb-2.5 px-0.5">
                <Sparkles size={13} className="text-green-400" />
                <h3 className="text-[11px] font-bold text-white uppercase tracking-wider">Your Creations</h3>
                <span className="text-[9px] text-gray-600 ml-auto">{assets.length}</span>
            </div>

            {/* Expanded detail — rendered above the grid so player & controls stay in view */}
            <AnimatePresence>
                {sel && (
                    <motion.div
                        key={sel.id}
                        data-testid="asset-spotlight-detail"
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: 'auto' }}
                        exit={{ opacity: 0, height: 0 }}
                        className="overflow-hidden mb-2.5"
                    >
                        <div className="p-2.5 rounded-lg bg-black/30 border border-white/5">
                            {/* Preview */}
                            <div className="w-full aspect-video rounded-md overflow-hidden bg-gray-900 mb-2 relative">
                                {sel.type === 'video' ? (
                                    <video src={sel.url} className="w-full h-full object-cover" controls playsInline />
                                ) : sel.type === 'image' ? (
                                    <img src={sel.url} alt="" className="w-full h-full object-contain bg-black" />
                                ) : (
                                    <div className="w-full h-full flex items-center justify-center">
                                        {React.createElement(BADGE[sel.type]?.icon || Image, { size: 28, className: 'text-gray-600' })}
                                    </div>
                                )}
                            </div>
                            <p className="text-[11px] text-gray-300 line-clamp-2 mb-1.5 leading-snug">{sel.prompt}</p>
                            <div className="flex flex-wrap gap-1.5 text-[9px] text-gray-500 mb-2">
                                <span>{relTime(sel.timestamp)}</span>
                                {sel.category && <span>· {sel.category}</span>}
                            </div>
                            <div className="flex gap-1.5">
                                <button
                                    onClick={() => handleDiscuss(sel)}
                                    className="flex items-center gap-1 px-2 py-1 rounded-md bg-green-500/15 text-green-400 text-[10px] font-medium hover:bg-green-500/25 transition-colors"
                                >
                                    <MessageCircle size={10} />
                                    Discuss
                                </button>
                                <button
                                    onClick={() => openInStudio(sel)}
                                    className="flex items-center gap-1 px-2 py-1 rounded-md bg-white/5 text-gray-400 text-[10px] font-medium hover:bg-white/10 transition-colors"
                                >
                                    <Maximize2 size={10} />
                                    Studio
                                </button>
                                <button
                                    onClick={() => setSelIdx(null)}
                                    aria-label="Close selected creation"
                                    className="ml-auto p-1 rounded text-gray-600 hover:text-gray-300 transition-colors"
                                >
                                    <X size={12} />
                                </button>
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Grid — 2 columns */}
            <div className="grid grid-cols-2 gap-2">
                {assets.map((asset, i) => {
                    const badge = BADGE[asset.type] ?? BADGE['image']!;
                    const BadgeIcon = badge.icon;
                    const isSelected = selIdx === i;
                    return (
                        <motion.button
                            key={asset.id}
                            onClick={() => setSelIdx(isSelected ? null : i)}
                            className={`rounded-lg overflow-hidden border transition-all text-left flex flex-col ${isSelected
                                ? 'border-green-500/50 ring-1 ring-green-500/20'
                                : 'border-white/5 hover:border-white/15'
                                }`}
                            initial={{ opacity: 0, scale: 0.95 }}
                            animate={{ opacity: 1, scale: 1 }}
                            transition={{ delay: i * 0.02 }}
                        >
                            {/* Thumbnail */}
                            <div className="aspect-square bg-gray-900 relative overflow-hidden w-full">
                                {asset.type === 'video' ? (
                                    <video
                                        src={asset.url}
                                        className="w-full h-full object-cover"
                                        preload="metadata"
                                        muted
                                        loop
                                        playsInline
                                        onMouseEnter={(e) => {
                                            e.currentTarget.play().catch((err: unknown) => {
                                                // Browser aborted play (usually due to autoplay restrictions or navigation transitions)
                                                if (err instanceof Error && err.name !== 'AbortError') {
                                                    console.error('Asset video failed to play:', err);
                                                }
                                            });
                                        }}
                                        onMouseLeave={(e) => { e.currentTarget.pause(); e.currentTarget.currentTime = 0; }}
                                    />
                                ) : asset.type === 'image' ? (
                                    <img
                                        src={asset.thumbnailUrl || asset.url}
                                        alt={asset.prompt}
                                        className="w-full h-full object-cover"
                                        loading="lazy"
                                        decoding="async"
                                    />
                                ) : (
                                    <div className="w-full h-full flex items-center justify-center bg-linear-to-br from-gray-800 to-gray-900">
                                        <BadgeIcon size={24} className="text-gray-600" />
                                    </div>
                                )}
                                {/* Badge */}
                                <div className={`absolute top-1.5 left-1.5 flex items-center gap-0.5 px-1 py-0.5 rounded text-[8px] font-medium backdrop-blur-sm ${badge.cls}`}>
                                                    avatarUrl={msg.role === 'user' ? (userProfile?.photoURL ?? undefined) : undefined}
                                                    variant="compact"
                                                />
                                            ))}
                                            {isAgentProcessing && (
                                                <div className="flex items-center gap-2 px-3 py-2 text-gray-500 text-xs">
                                                    <Sparkles size={12} className="animate-pulse text-green-400" />
                                                    indii is thinking…
                                                </div>
                                            )}
                                        </div>
                                    )}
                                </div>

                                {/* Inline PromptArea for Right Panel */}
                                <div className="p-4 border-t border-border bg-black/20 shrink-0">
                                    <PromptArea isDocked className="static! translate-x-0! w-full! max-w-none! shadow-none border-none bg-transparent" />
                                </div>

                                {/* Maestro Batching Status */}
                                <BatchingStatus />

                                {/* Asset Spotlight integration — collapsible */}
                                <div className="border-t border-green-500/25 bg-gradient-to-r from-green-500/10 via-green-500/5 to-transparent shrink-0">
                                    <button
                                        onClick={() => {
                                            setIsCreationsCollapsed(prev => !prev);
                                            acknowledgeCreationsAffordance();
                                        }}
                                        className="w-full flex items-center justify-between px-4 py-2.5 hover:bg-green-500/10 transition-colors group"
                                        aria-label={isCreationsCollapsed ? 'Expand Your Creations' : 'Collapse Your Creations'}
                                        aria-expanded={!isCreationsCollapsed}
                                        data-testid="toggle-creations-btn"
                                    >
                                        <h4 className="text-[10px] uppercase tracking-wider text-green-300/90 font-bold flex items-center gap-2 group-hover:text-green-200 transition-colors">
                                            <Sparkles size={11} className={isCreationsCollapsed && shouldPulseCreations ? "text-green-400 animate-pulse" : "text-green-400"} />
                                            Your Creations
                                            {generatedHistory.length > 0 && (
                                                <span className="ml-auto mr-2 px-1.5 py-0.5 text-[8px] font-mono bg-green-400/20 text-green-300 rounded border border-green-400/40">
                                                    {generatedHistory.length}
                                                </span>
                                            )}
                                        </h4>
                                        {isCreationsCollapsed ? (
                                            <ChevronUp size={12} className="text-green-400/70 group-hover:text-green-300 transition-colors" />
                                        ) : (
                                            <ChevronDown size={12} className="text-green-400/70 group-hover:text-green-300 transition-colors" />
                                        )}
                                    </button>
                                    <motion.div
                                        initial={false}
                                        animate={{
                                            height: isCreationsCollapsed ? 0 : 'auto',
                                            opacity: isCreationsCollapsed ? 0 : 1
                                        }}
                                        transition={{ duration: 0.25, ease: 'easeInOut' }}
                                        className="overflow-hidden"
                                    >
                                        <div className="px-4 pb-4 max-h-[40vh] overflow-y-auto overscroll-contain">
                                            <AssetSpotlight />
                                        </div>
                                    </motion.div>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            );
        }

        // TAB 2: ASSETS

