private async finalizeOwnedGraph(
    userId: string,
    executionId: string,
    runnerId: string,
    status: 'COMPLETED' | 'FAILED',
): Promise<void> {
    const ref = doc(db, 'users', userId, 'graphExecutions', executionId);
    try {
        await runTransaction(db, async tx => {
            const snap = await tx.get(ref);
            const state = snap.exists() ? snap.data() as GraphExecutionState : undefined;
            const lease = state && currentGraphLease(state);
            if (!state || lease?.holderId !== runnerId || !Number.isFinite(lease.expiresAt) ||
                lease.expiresAt <= Date.now() ||
                (state.status !== status &&
                    (state.status === 'CANCELLED' || state.status === 'FAILED' || state.status === 'COMPLETED'))) {
                throw new GraphResultCheckpointError(`Graph execution ${executionId} lost ownership before finalization.`);
            }
            if (state.status === status) return;
            tx.update(ref, { status, updatedAt: serverTimestamp() });
        });
    } catch (error) {
        if (error instanceof GraphResultCheckpointError) throw error;
        throw new GraphResultCheckpointError(`Graph execution ${executionId} final status could not be verified.`, { cause: error });
    }
}

private async saveClaimedNodeResult(
    userId: string,
    executionId: string,
    runnerId: string,
    nodeId: string,
    result: { status: 'STEP_COMPLETE'; output: string } | { status: 'FAILED'; error: string },
): Promise<void> {
    const ref = doc(db, 'users', userId, 'graphExecutions', executionId);
    try {
        await runTransaction(db, async tx => {
            const snap = await tx.get(ref);
            const state = snap.exists() ? snap.data() as GraphExecutionState : undefined;
            const lease = state && currentGraphLease(state);
            if (!state || lease?.holderId !== runnerId || !Number.isFinite(lease.expiresAt) ||
                lease.expiresAt <= Date.now() ||
                state.status === 'CANCELLED' || state.status === 'FAILED' || state.status === 'COMPLETED' ||
                state.nodeStates?.[nodeId]?.status !== 'EXECUTING_GENERATION') {
                throw new GraphResultCheckpointError(`Graph execution ${executionId} lost its lease before saving node ${nodeId}.`);
            }
            const path = `nodeStates.${nodeId}`;
            tx.update(ref, {
                [`${path}.status`]: result.status,
                [`${path}.completedAt`]: Date.now(),
                ...(result.status === 'STEP_COMPLETE'
                    ? { [`${path}.output`]: result.output }
                    : { [`${path}.error`]: result.error }),
                updatedAt: serverTimestamp(),
            });
        });
    } catch (error) {
        if (error instanceof GraphResultCheckpointError) throw error;
        throw new GraphResultCheckpointError(
            `Graph node ${nodeId} result could not be verified; reconcile the saved outcome before retrying.`,
            { cause: error },
        );
    }
}

/**
 * Atomically claim a node for execution. The readiness computation in
 * runGraphLoopInternal reads a state snapshot; two loop instances can
 * observe the same PLANNED node from their own snapshots. This
 * transaction only succeeds while the node is still PLANNED, so exactly
 * one loop wins each node — the loser's claim returns false and the node
 * is skipped, never double-executed.
 */
private async claimNodeAtomically(
    userId: string,
    executionId: string,
    nodeId: string,
    runnerId: string,
): Promise<'CLAIMED' | 'NOT_READY' | 'LEASE_LOST'> {
    const ref = doc(db, 'users', userId, 'graphExecutions', executionId);
    try {
        return await runTransaction(db, async (tx) => {
            const snap = await tx.get(ref);
            if (!snap.exists()) return 'LEASE_LOST';
            const data = snap.data() as {
                status?: GraphExecutionState['status'];
                nodeStates?: Record<string, { status?: string }>;
                metadata?: { lease?: GraphExecutionState['lease'] };
                lease?: GraphExecutionState['lease'];
            };
            if (data.status === 'CANCELLED' || data.status === 'FAILED' || data.status === 'COMPLETED') {
                return 'LEASE_LOST';
            }
            const lease = currentGraphLease(data);
            if (lease?.holderId !== runnerId || !Number.isFinite(lease.expiresAt) || lease.expiresAt <= Date.now()) {
                return 'LEASE_LOST';
            }
            const nodeState = data.nodeStates?.[nodeId];
            if (!nodeState || nodeState.status !== 'PLANNED') return 'NOT_READY';
            tx.update(ref, {
                [`nodeStates.${nodeId}.status`]: 'EXECUTING_GENERATION',
                [`nodeStates.${nodeId}.startedAt`]: Date.now(),
                status: 'EXECUTING',
            });
            return 'CLAIMED';
        });
    } catch (error) {
        logger.warn(`[AgentGraph] Atomic claim failed for node ${nodeId} in ${executionId}:`, error);
        throw new Error(`Graph node ${nodeId} claim could not be verified; no action was dispatched.`, { cause: error });
    }
}

