#!/usr/bin/env node
/**
 * Records real TypeSafe (Jev) Boardroom judgments for the prompts the Boardroom
 * e2e specs send — the intent gate plus, for the action path, orchestration
 * complexity and specialist/corpus routing — so the shared fixture answers
 * `typesafeJudge` the way the real judge does instead of blanket defaults.
 *
 *   NODE_USE_ENV_PROXY=1 node scripts/record-boardroom-judgments.mjs
 *
 * Uses the shipped question definitions (bundled from
 * packages/renderer/src/config/typesafeJudgments.ts), so a question change is
 * picked up on the next recording. Auth: TYPESAFE_API_KEY if set; in agent
 * sandboxes the egress proxy injects the credential. The key is never printed
 * or written. Writes e2e/fixtures/boardroomJudgments.json.
 *
 * Evidence class: recorded live judgments with an empty recentConversation and
 * activeModule 'dashboard' (the module e2e lands on) — an approximation of
 * in-app judging (which sees prior turns), not a replay.
 */
import { build } from 'esbuild';
import { writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = join(root, 'e2e/fixtures/boardroomJudgments.json');
const ENDPOINT = 'https://api.typesafe.ai/v1/systemone';
const MODEL = 'jev-latest';

/** Every prompt a Boardroom e2e spec submits. Keep in sync when adding specs. */
const PROMPTS = [
    // workflow-strategic-goal.spec.ts
    "Let's plan a Detroit tour with the new album art",
    'Creative Director generate the art, Road Director plan Detroit advance',
    'Imagery and dates are locked. Trigger rollout.',
    'Generate rollout materials and schedule drafts',
    'We are done. Clear the boardroom table.',
    // boardroom-real-user-scenario.spec.ts
    "Let's bring in Marketing and Finance",
    'How much should we spend on this campaign?',
    "Let's bring in Legal to check the agreements",
    'Marketing and Finance, you are good to go, thank you',
    'Legal, what templates are we using and what is the visual split sheet agreement?',
    "Creative and Video, let's generate a marketing visual for this campaign.",
    "Social and Publicist, let's outline the social copy and write a press release hook.",
    "Brand and Music, let's align on the artistic vibe",
    'Thank you team, we are done for today. Clear the table.',
];

async function loadQuestions() {
    const dir = mkdtempSync(join(tmpdir(), 'boardroom-judgments-'));
    const outfile = join(dir, 'questions.mjs');
    await build({
        stdin: {
            contents: `export {
                BOARDROOM_INTENT_QUESTION, BOARDROOM_INTENT_MIN_CONFIDENCE,
                ORCHESTRATION_COMPLEXITY_QUESTION, SPECIALIST_ROUTE_QUESTION, RAG_CORPUS_ROUTE_QUESTION,
            } from './packages/renderer/src/config/typesafeJudgments.ts';`,
            resolveDir: root,
            loader: 'ts',
        },
        bundle: true,
        platform: 'node',
        format: 'esm',
        outfile,
        alias: { '@': join(root, 'packages/renderer/src'), '@indii/shared': join(root, 'packages/shared/src/index.ts') },
        define: { 'import.meta.env': '{}' },
        logLevel: 'error',
    });
    return import(pathToFileURL(outfile).href);
}

async function judge(state, questions) {
    const res = await fetch(ENDPOINT, {
        method: 'POST',
        headers: { Authorization: `Bearer ${process.env.TYPESAFE_API_KEY || 'proxy-injected'}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: MODEL, state, questions }),
        signal: AbortSignal.timeout(30_000),
    });
    if (!res.ok) throw new Error(`TypeSafe HTTP ${res.status}`);
    return res.json();
}

const {
    BOARDROOM_INTENT_QUESTION, BOARDROOM_INTENT_MIN_CONFIDENCE,
    ORCHESTRATION_COMPLEXITY_QUESTION, SPECIALIST_ROUTE_QUESTION, RAG_CORPUS_ROUTE_QUESTION,
} = await loadQuestions();

const pick = (answer, label, prompt) => {
    const { choice, confidence } = answer ?? {};
    if (typeof choice !== 'string' || typeof confidence !== 'number') throw new Error(`Unexpected ${label} judgment for: ${prompt}`);
    return { choice, confidence };
};

// Same state shapes the app sends (judgeBoardroomIntent, judgeOrchestrationComplexity,
// judgeSpecialistAgentRoute in typesafeJudgments.ts).
const judgments = {};
let inputTokens = 0;
let outputTokens = 0;
const tally = (result) => {
    inputTokens += result.usage?.input_tokens ?? 0;
    outputTokens += result.usage?.output_tokens ?? 0;
};
for (const prompt of PROMPTS) {
    const intentResult = await judge({ query: prompt, recentConversation: '', attachedImageCount: 0 }, { intent: BOARDROOM_INTENT_QUESTION });
    const complexityResult = await judge({ query: prompt }, { complexity: ORCHESTRATION_COMPLEXITY_QUESTION });
    const routeResult = await judge(
        { query: prompt, activeModule: 'dashboard', hasSourceAssets: false },
        { specialist: SPECIALIST_ROUTE_QUESTION, corpus: RAG_CORPUS_ROUTE_QUESTION },
    );
    [intentResult, complexityResult, routeResult].forEach(tally);
    const entry = {
        intent: pick(intentResult.answers?.intent, 'intent', prompt),
        complexity: pick(complexityResult.answers?.complexity, 'complexity', prompt),
        specialist: pick(routeResult.answers?.specialist, 'specialist', prompt),
        corpus: pick(routeResult.answers?.corpus, 'corpus', prompt),
    };
    judgments[prompt] = entry;
    const fmt = ({ choice, confidence }) => `${choice}@${confidence.toFixed(2)}`;
    console.log(`${fmt(entry.intent).padEnd(16)} ${fmt(entry.complexity).padEnd(15)} ${fmt(entry.specialist).padEnd(18)} ${prompt}`);
}
writeFileSync(OUT, `${JSON.stringify({
    $comment: 'Generated by scripts/record-boardroom-judgments.mjs from live TypeSafe (jev-latest) with the shipped judgment questions. Do not edit by hand.',
    model: MODEL,
    minConfidence: BOARDROOM_INTENT_MIN_CONFIDENCE,
    judgments,
}, null, 2)}\n`);
console.log(`wrote ${OUT} (${PROMPTS.length} prompts, ${inputTokens} input / ${outputTokens} output tokens)`);
#!/usr/bin/env node
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { parseIssueLedger } from './issue-ledger-integrity.mjs';

// Anchor lifecycle words: “code complete, live proof pending” is not closed.
export function classifyIssueStatus(status) {
  const text = status.replace(/^[^\p{L}]*/u, '').trim();
  if (/^(?:FIXED|CLOSED|COMPLETED|COMPLETE|DONE|RESOLVED|WONTFIX)\b/i.test(text)) return 'terminal';
  if (/^RESEARCH COMPLETE\b/i.test(text)) return 'decision';
  if (/^(?:OPEN|PARTIAL|BACKLOG|BLOCKED|PLANNED|FOUNDER-GATED|IMPLEMENTED|FIX IN FLIGHT|ISOLATED|CODE COMPLETE)\b/i.test(text)) return 'nonterminal';
  return 'ambiguous';
}

export function inventoryIssueLedger(markdown) {
  const grouped = new Map();
  for (const entry of parseIssueLedger(markdown)) {
    const record = {
      title: entry.title,
      status: entry.status,
      classification: classifyIssueStatus(entry.status),
    };
    const existing = grouped.get(entry.id) ?? [];
    existing.push(record);
    grouped.set(entry.id, existing);
  }
  const issues = [...grouped].map(([id, entries]) => {
    // A duplicate with an unresolved or unknown status cannot disappear behind
    // a terminal companion. Report every original title and status for review.
    const states = entries.map(entry => entry.classification);
    const classification = ['ambiguous', 'nonterminal', 'decision', 'terminal']
      .find(state => states.includes(state));
    return { id, classification, entries };
  }).sort((a, b) => Number(a.id) - Number(b.id));
  return {
    numberedEntries: [...grouped.values()].reduce((sum, entries) => sum + entries.length, 0),
    uniqueIds: issues.length,
    terminal: issues.filter(issue => issue.classification === 'terminal').length,
    decisions: issues.filter(issue => issue.classification === 'decision').length,
    nonterminal: issues.filter(issue => issue.classification === 'nonterminal').length,
    ambiguous: issues.filter(issue => issue.classification === 'ambiguous').length,
    duplicateIds: issues.filter(issue => issue.entries.length > 1).map(issue => issue.id),
    issues,
  };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const inventory = inventoryIssueLedger(readFileSync('.agent/test_ledger/OPEN_ISSUES_V3.md', 'utf8'));
  if (process.argv.includes('--json')) {
    console.log(JSON.stringify(inventory, null, 2));
  } else {
    console.log(`Numbered entries: ${inventory.numberedEntries}; unique IDs: ${inventory.uniqueIds}`);
    console.log(`Terminal: ${inventory.terminal}; decisions: ${inventory.decisions}; nonterminal: ${inventory.nonterminal}; ambiguous: ${inventory.ambiguous}`);
    console.log(`Historical duplicate IDs: ${inventory.duplicateIds.join(', ') || 'none'}`);
    console.log('Ledger classification only; terminal labels are not independently verified closure evidence.');
    for (const issue of inventory.issues.filter(issue => issue.classification !== 'terminal')) {
      console.log(`ISSUE-${issue.id} [${issue.classification}]: ${issue.entries.map(entry => entry.status || '(missing status)').join(' | ')}`);
    }
  }
}
const ISSUE_HEADING = /^### ISSUE-(\d+):\s*(.+?)\s*$/gm;
const STATUS = /^- \*\*Status:\*\*\s*(.+)$/m;

export function parseIssueLedger(markdown) {
  const headings = [...markdown.matchAll(ISSUE_HEADING)];
  return headings.map((match, index) => {
    const section = markdown.slice(match.index, headings[index + 1]?.index ?? markdown.length);
    return {
      id: match[1],
      title: match[2],
      status: section.match(STATUS)?.[1] ?? '',
      section,
    };
  });
}

/** Compare against a fresh base so historical duplicates are preserved, never expanded. */
export function validateIssueLedger(baseMarkdown, candidateMarkdown) {
  const base = parseIssueLedger(baseMarkdown);
  const candidate = parseIssueLedger(candidateMarkdown);
  const failures = [];
  const key = issue => `${issue.id}\u0000${issue.title}`;
  const baseCounts = new Map();
  const candidateCounts = new Map();
  const baseIds = new Set(base.map(issue => issue.id));

  for (const issue of base) baseCounts.set(key(issue), (baseCounts.get(key(issue)) ?? 0) + 1);
  for (const issue of candidate) candidateCounts.set(key(issue), (candidateCounts.get(key(issue)) ?? 0) + 1);

  for (const [identity, count] of baseCounts) {
    if ((candidateCounts.get(identity) ?? 0) < count) {
      const [id, title] = identity.split('\u0000');
      failures.push(`ISSUE-${id}: existing finding removed or renamed (${title}).`);
    }
  }

  for (const issue of candidate) {
    const identity = key(issue);
    const priorCount = baseCounts.get(identity) ?? 0;
    const nextCount = candidateCounts.get(identity) ?? 0;
    if (baseIds.has(issue.id) && priorCount === 0) {
      failures.push(`ISSUE-${issue.id}: identifier reused for another finding (${issue.title}).`);
    } else if (nextCount > Math.max(priorCount, 1)) {
      failures.push(`ISSUE-${issue.id}: duplicate finding added (${issue.title}).`);
    }
  }

  // A resolved status must be paired with newly added evidence in that finding.
  for (const issue of candidate) {
    const previous = base.find(entry => key(entry) === key(issue));
    if (!previous) continue;
    const wasResolved = /(?:FIXED|COMPLETED|CLOSED)/i.test(previous.status);
    const isResolved = /(?:FIXED|COMPLETED|CLOSED)/i.test(issue.status);
    const closure = issue.section.match(/^[-*] \*\*Closure evidence:\*\* (.+)$/m)?.[1] ?? '';
    const priorClosure = previous.section.match(/^[-*] \*\*Closure evidence:\*\* (.+)$/m)?.[1] ?? '';
    if (!wasResolved && isResolved &&
        (!/\bcommit [0-9a-f]{7,40}\b/i.test(closure) ||
         !/\bCI https:\/\/github\.com\/[^\s]+\/actions\/runs\/\d+\b/i.test(closure) ||
         closure === priorClosure)) {
      failures.push(`ISSUE-${issue.id}: resolved status needs newly added Closure evidence.`);
    }
  }

  return [...new Set(failures)];
}

