export const BOARDROOM_BOOKMARKS: readonly QuickBookmark[] = [
    { id: 'spotify', title: 'Spotify for Artists', url: 'https://artists.spotify.com', badge: 'DSP' },
    { id: 'apple', title: 'Apple Music', url: 'https://artists.apple.com', badge: 'DSP' },
