import fs from 'fs';
import path from 'path';
import { pathToFileURL } from 'url';

const STATE_FILE_PATH = path.resolve('.agent/checkpoints/polling_state.json');
const LOG_FILE_PATH = path.resolve('.agent/logs/git_monitor.log');

