        if (node.isTrashed) return false;
        const matchesSearch = node.name.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesFilter = filterType === 'all' || node.fileType === filterType;
        return matchesSearch && matchesFilter;
    });

