                    <NavItem
                        icon={Clock}
                        label="Recent"
                        active={activeTab === 'active' && filterType === 'all'}
                        onClick={() => {
                            setActiveTab('active');
                            setFilterType('all');
                        }}
                    />
                    <NavItem icon={Star} label="Favorites" />

                    <div className="mt-8 mb-2 px-3 text-[10px] font-bold text-gray-500 uppercase tracking-widest">Media Types</div>
                    <NavItem
