                        label="Images"
                        count={fileNodes.filter((n: FileNode) => n.fileType === 'image' && !n.isTrashed).length}
                        onClick={() => {
                            setActiveTab('active');
                            setFilterType('image');
                        }}
                        active={activeTab === 'active' && filterType === 'image'}
                    />
                    <NavItem
                        icon={Video}
                        label="Video"
                        count={fileNodes.filter((n: FileNode) => n.fileType === 'video' && !n.isTrashed).length}
                        onClick={() => {
                            setActiveTab('active');
                            setFilterType('video');
                        }}
                        active={activeTab === 'active' && filterType === 'video'}
                    />
                    <NavItem
                        icon={Music}
                        label="Audio DNA"
                        count={fileNodes.filter((n: FileNode) => n.fileType === 'audio' && !n.isTrashed).length}
                        onClick={() => {
                            setActiveTab('active');
                            setFilterType('audio');
                        }}
                        active={activeTab === 'active' && filterType === 'audio'}
                    />
                    <NavItem
                        icon={FileText}
                        label="Documents"
                        count={fileNodes.filter((n: FileNode) => n.fileType === 'document' && !n.isTrashed).length}
                        onClick={() => {
                            setActiveTab('active');
                            setFilterType('document');
                        }}
                        active={activeTab === 'active' && filterType === 'document'}
                    />

                    <div className="mt-8 mb-2 px-3 text-[10px] font-bold text-gray-500 uppercase tracking-widest">Locations</div>
                    <NavItem
                        icon={Folder}
                        label="All Files"
                        onClick={() => {
                            setActiveTab('active');
                            setFilterType('all');
                        }}
                        active={activeTab === 'active' && filterType === 'all'}
                    />
                    <NavItem
                        icon={Trash2}
                        label="Trash Vault"
                        count={trashItems.length}
                        onClick={() => {
                            setActiveTab('trash');
                        }}
                        active={activeTab === 'trash'}
                    />

                    {activeTab === 'active' && (
                        <div className="mt-4 px-2">
                            <FileTree nodes={fileNodes.filter(n => !n.isTrashed)} parentId={null} />
                        </div>
                    )}
                </nav>
            </div>

            {/* Main Content */}
            <div className="flex-1 flex flex-col z-10 min-w-0">
                {/* Top Toolbar */}
                <div className="h-20 border-b border-white/5 flex items-center justify-between px-8 bg-surface/20 backdrop-blur-md">
                    <div className="relative w-96">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" size={16} />
                        <input
                            type="text"
                                <LayoutGrid size={14} />
                                <span>Spatial Canvas</span>
                            </button>
                            <button
                                data-testid="project-view-files"
                                className="flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-semibold bg-white/10 text-white shadow-sm transition-colors"
                            >
                                <FolderTree size={14} />
                                <span>File Explorer</span>
                            </button>
                        </div>

                        <div className="flex items-center gap-2 bg-black/20 p-1 rounded-lg border border-white/5">
                            <button
                                onClick={() => setViewMode('grid')}
                                className={cn('p-2 rounded-md transition-colors', viewMode === 'grid' ? 'bg-white/10 text-white shadow-sm' : 'text-gray-500 hover:text-gray-300')}
                            >
                                <Grid size={16} />
                            </button>
                            <button
