            <div role="status">{pathname}{search}</div>
            <MerchStudio />
        </>
    );
}

describe('MerchStudio routing', () => {
    it.each(['/dashboard', '/project-canvas?view=files'])('preserves a transition to %s while Merchandise is still mounted', async (destination) => {
